<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue'

useHead({ title: '網站編輯器', meta: [{ name: 'robots', content: 'noindex, nofollow, noarchive' }] })

const workspace = ref<any>(null)
const page = ref<any>(null)
const versions = ref<any[]>([])
const selectedPageId = ref('')
const selectedBlockId = ref('')
const device = ref<'desktop' | 'tablet' | 'mobile'>('desktop')
const status = ref<'loading' | 'saved' | 'saving' | 'publishing' | 'published' | 'error' | 'conflict'>('loading')
const message = ref('')
const mediaOpen = ref(false)
const mediaQuery = ref('')
const uploading = ref<Record<string, number>>({})
const aiRequest = ref('')
const aiProposal = ref<any>(null)
const aiLoading = ref(false)
const previewArtifact = ref<any>(null)
const undoVersions = ref<number[]>([])
const redoVersions = ref<number[]>([])
const draggedBlockId = ref('')
const cropAspect = ref('16:9')
const focalX = ref(.5)
const focalY = ref(.5)
const collectionName = ref('')
const tagName = ref('')

const selectedBlock = computed(() => page.value?.sections?.find((block: any) => block.blockId === selectedBlockId.value) || null)
const filteredAssets = computed(() => (workspace.value?.assets || []).filter((asset: any) => !mediaQuery.value || `${asset.filename} ${(asset.tags || []).map((tag: any) => tag.name).join(' ')}`.toLowerCase().includes(mediaQuery.value.toLowerCase())))
const quotaPercent = computed(() => { const quota = workspace.value?.quota; return quota ? Math.min(100, Math.round((quota.originalBytesUsed / Math.max(1, quota.maxOriginalBytes)) * 100)) : 0 })
const blockCatalog: Array<[string, string]> = [
  ['hero', '主視覺'], ['rich_text', '文字'], ['image_text', '圖文'], ['services', '服務'], ['case_studies', '案例'], ['gallery_grid', '相簿'], ['carousel', '輪播'], ['team', '團隊'], ['testimonials', '見證'], ['faq', 'FAQ'], ['cta', '行動呼籲'], ['article_list', '文章列表'], ['contact', '聯絡'], ['booking_intent', '預約'], ['spacer', '留白'], ['divider', '分隔線'],
]
const variants: Record<string, string[]> = { hero: ['split', 'overlay', 'centered'], rich_text: ['prose', 'columns'], image_text: ['split', 'stacked'], services: ['cards', 'list', 'featured'], case_studies: ['cards', 'editorial', 'masonry'], gallery_grid: ['grid', 'masonry'], carousel: ['contained', 'edge'], team: ['cards', 'portraits'], testimonials: ['cards', 'quotes'], faq: ['accordion', 'list'], cta: ['band', 'card'], article_list: ['cards', 'list'], contact: ['form', 'split'], booking_intent: ['form', 'card'], spacer: ['default'], divider: ['default'] }

function errorText(error: any) { return error?.data?.message || error?.data?.statusMessage || error?.message || '操作失敗，沒有覆寫任何內容。' }
function key(prefix: string) { return `${prefix}:${Date.now()}:${crypto.randomUUID()}` }
async function loadWorkspace() {
  status.value = 'loading'; message.value = ''
  try { workspace.value = await $fetch('/api/managed-sites/editor/workspace'); selectedPageId.value ||= workspace.value.pages?.[0]?.pageId || ''; if (selectedPageId.value) await loadPage(selectedPageId.value); status.value = 'saved' } catch (error) { status.value = 'error'; message.value = errorText(error) }
}
async function loadPage(pageId: string) {
  const result: any = await $fetch(`/api/managed-sites/editor/pages/${encodeURIComponent(pageId)}`); page.value = result.page; versions.value = result.versions || []; selectedBlockId.value = page.value.sections?.[0]?.blockId || ''; previewArtifact.value = null
}
async function choosePage() { if (selectedPageId.value) await loadPage(selectedPageId.value) }
async function applyCommand(type: string, target: any, payload: any, reason: string) {
  if (!page.value) return; status.value = 'saving'; message.value = ''
  try { const previous = page.value.version; const result: any = await $fetch(`/api/managed-sites/editor/pages/${encodeURIComponent(page.value.pageId)}/commands`, { method: 'POST', body: { schemaVersion: 'managed-site-page-command-v1', type, expectedPageVersion: previous, idempotencyKey: key('editor'), target, payload, reason } }); undoVersions.value.push(previous); redoVersions.value = []; page.value = result.page; versions.value.unshift(result.page); status.value = 'saved' }
  catch (error: any) { status.value = error?.statusCode === 409 || error?.response?.status === 409 ? 'conflict' : 'error'; message.value = errorText(error) }
}
async function saveText(path: string, value: string) { if (selectedBlock.value && value.trim()) await applyCommand('update_text', { blockId: selectedBlock.value.blockId, path }, value, '客戶在屬性面板更新文字') }
async function updateVariant(value: string) { await applyCommand('update_block_variant', { blockId: selectedBlock.value.blockId }, value, '客戶選擇受控區塊版型') }
async function toggleVisibility() { await applyCommand('toggle_visibility', { blockId: selectedBlock.value.blockId }, !selectedBlock.value.visible, '客戶切換區塊顯示狀態') }
async function moveBlock(blockId: string, direction: number) { const index = page.value.sections.findIndex((block: any) => block.blockId === blockId); const toIndex = Math.max(0, Math.min(page.value.sections.length - 1, index + direction)); if (toIndex !== index) await applyCommand('move_block', { blockId }, { toIndex }, '客戶重新排序區塊') }
async function dropBlock(targetIndex: number) { if (!draggedBlockId.value) return; const source = page.value.sections.findIndex((block: any) => block.blockId === draggedBlockId.value); if (source >= 0 && source !== targetIndex) await applyCommand('move_block', { blockId: draggedBlockId.value }, { toIndex: targetIndex }, '客戶拖曳重新排序區塊'); draggedBlockId.value = '' }
async function removeBlock() { if (selectedBlock.value && confirm('將此區塊移出目前草稿？已發布版本不會直接改變。')) await applyCommand('remove_block', { blockId: selectedBlock.value.blockId }, null, '客戶移除草稿區塊') }
function defaultBlock(type: string) {
  const blockId = `block_${crypto.randomUUID().replaceAll('-', '').slice(0, 16)}`; const base: any = { blockId, type, visible: true, layoutVariant: variants[type]?.[0] || 'default', mediaBindingIds: [], schedule: null }
  const ready = (workspace.value.assets || []).filter((asset: any) => asset.status === 'ready' && asset.sha256); const selected = type === 'image_text' ? ready.slice(0, 1) : ['gallery_grid', 'carousel'].includes(type) ? ready.slice(0, 6) : []; const mediaBindings = selected.map((asset: any, index: number) => ({ bindingId: `binding_${crypto.randomUUID().replaceAll('-', '').slice(0, 14)}_${index}`, assetId: asset.assetId, assetVersion: asset.version, assetSha256: asset.sha256, role: type === 'image_text' ? 'content' : 'gallery', alt: asset.filename, decorative: false, provenance: 'customer' })); base.mediaBindingIds = mediaBindings.map((binding: any) => binding.bindingId)
  const data: any = { hero: { title: '新的主視覺', description: '請輸入說明', alignment: 'left' }, rich_text: { nodes: [{ type: 'paragraph', text: '新的文字內容' }] }, image_text: { title: '新的圖文', description: '請輸入說明', mediaBindingId: mediaBindings[0]?.bindingId, imagePosition: 'left' }, services: { title: '服務', items: [{ id: 'service-1', title: '服務項目', description: '服務說明' }] }, case_studies: { title: '案例', items: [{ id: 'case-1', title: '案例標題', summary: '案例說明' }] }, gallery_grid: { columns: 3, gap: 'balanced', aspect: '4:3', captions: true, lightbox: true, mediaBindingIds: base.mediaBindingIds }, carousel: { autoplay: false, pauseControl: true, mobileMode: 'single', mediaBindingIds: base.mediaBindingIds }, team: { title: '團隊', members: [{ id: 'member-1', name: '成員姓名', role: '職務' }] }, testimonials: { items: [{ id: 'quote-1', quote: '客戶見證', person: '客戶姓名' }] }, faq: { title: '常見問題', items: [{ id: 'faq-1', question: '問題', answer: '回答' }] }, cta: { title: '準備開始了嗎？', primaryLink: { label: '聯絡我們', href: '/contact' } }, article_list: { title: '最新文章', source: 'latest', limit: 6 }, contact: { title: '聯絡我們', fields: ['name', 'email', 'message'], consentRequired: true }, booking_intent: { title: '預約諮詢', serviceKeys: ['consultation'], collectsPayment: false }, spacer: { size: 'md' }, divider: { style: 'line' } }[type]
  if (['image_text', 'gallery_grid', 'carousel'].includes(type) && !selected.length) return null; const block = { ...base, data }; return mediaBindings.length ? { block, mediaBindings } : block
}
async function addBlock(type: string) { const payload = defaultBlock(type); if (!payload) { mediaOpen.value = true; message.value = '此區塊需要先選擇已處理完成的媒體。'; return } await applyCommand('add_block', { index: page.value.sections.length }, payload, `客戶新增 ${type} 區塊`); selectedBlockId.value = payload.block?.blockId || payload.blockId }
async function duplicateBlock() { const newBlockId = `block_${crypto.randomUUID().replaceAll('-', '').slice(0, 16)}`; await applyCommand('duplicate_block', { blockId: selectedBlock.value.blockId }, { newBlockId }, '客戶複製區塊'); selectedBlockId.value = newBlockId }
async function scheduleBlock(until: string) { if (!until) return; await applyCommand('schedule_visibility', { blockId: selectedBlock.value.blockId }, { visibleFrom: null, visibleUntil: new Date(until).toISOString(), timezone: 'Asia/Taipei' }, '客戶設定區塊下架時間') }
async function restoreDraft(version: number, fromRedo = false) { if (!page.value || version === page.value.version) return; const current = page.value.version; status.value = 'saving'; try { const result: any = await $fetch(`/api/managed-sites/editor/pages/${encodeURIComponent(page.value.pageId)}/restore-draft`, { method: 'POST', body: { version, expectedPageVersion: current, idempotencyKey: key('restore'), reason: '客戶回復草稿版本' } }); if (fromRedo) undoVersions.value.push(current); else redoVersions.value.push(current); page.value = result.page; versions.value.unshift(result.page); status.value = 'saved' } catch (error) { status.value = 'conflict'; message.value = errorText(error) } }
async function undo() { const version = undoVersions.value.pop(); if (version) await restoreDraft(version) }
async function redo() { const version = redoVersions.value.pop(); if (version) await restoreDraft(version, true) }
async function requestPreview() { try { const result: any = await $fetch(`/api/managed-sites/editor/pages/${encodeURIComponent(page.value.pageId)}/preview`, { method: 'POST', body: { expectedPageVersion: page.value.version } }); previewArtifact.value = result.artifact; message.value = '已建立短效、noindex 的 server preview。' } catch (error) { message.value = errorText(error) } }
async function publish() { status.value = 'publishing'; try { const result: any = await $fetch(`/api/managed-sites/editor/pages/${encodeURIComponent(page.value.pageId)}/publish`, { method: 'POST', body: { expectedPageVersion: page.value.version, idempotencyKey: key('publish') } }); status.value = 'published'; message.value = `已建立發布意圖 ${result.receipt.receiptFingerprint.slice(0, 12)}…，等待既有 first-party publication/deployment authority 執行。` } catch (error) { status.value = 'error'; message.value = errorText(error) } }
async function uploadFiles(files: FileList | null) {
  if (!files?.length) return; const selected = [...files].slice(0, 25); for (const file of selected) { uploading.value[file.name] = 5; try { const intent: any = await $fetch('/api/managed-sites/editor/assets/upload-intent', { method: 'POST', body: { filename: file.name, declaredMime: file.type, declaredBytes: file.size, visibility: 'private', idempotencyKey: key('upload') } }); uploading.value[file.name] = 20; const headers = { ...intent.authorization.requiredHeaders }; delete (headers as any)['content-length']; const response = await fetch(intent.authorization.url, { method: 'PUT', headers, body: file, credentials: intent.authorization.url.startsWith('/') ? 'same-origin' : 'omit' }); if (!response.ok) throw new Error('物件上傳失敗'); uploading.value[file.name] = 70; await $fetch('/api/managed-sites/editor/assets/complete', { method: 'POST', body: { uploadId: intent.session.uploadId } }); uploading.value[file.name] = 100 } catch (error) { uploading.value[file.name] = -1; message.value = `${file.name}：${errorText(error)}` } } await loadWorkspace(); mediaOpen.value = true
}
async function replaceMedia(asset: any) { const block = selectedBlock.value; const bindingId = block?.mediaBindingIds?.[0]; const current = page.value.mediaBindings.find((binding: any) => binding.bindingId === bindingId); if (!bindingId || !current || asset.status !== 'ready' || !asset.sha256) { message.value = '請先選擇有圖片角色的區塊與 ready 素材。'; return } const binding = { ...current, assetId: asset.assetId, assetVersion: asset.version, assetSha256: asset.sha256, focalPoint: { x: focalX.value, y: focalY.value }, provenance: 'customer' }; await applyCommand('replace_media', { bindingId }, binding, `只替換目前 ${bindingId} 使用位置`); mediaOpen.value = false }
async function approveForPublicUse(asset: any) { if (!confirm('請確認你有權在此網站公開使用這張圖片；這不是法律合規判定。')) return; try { await $fetch(`/api/managed-sites/editor/assets/${encodeURIComponent(asset.assetId)}/governance`, { method: 'POST', body: { visibility: 'public', rightsMetadata: { publishAllowed: true, license: asset.rightsMetadata?.license || 'customer-confirmed' } } }); await loadWorkspace(); mediaOpen.value = true } catch (error) { message.value = errorText(error) } }
async function downloadOriginal(asset: any) { try { const result: any = await $fetch(`/api/managed-sites/editor/assets/${encodeURIComponent(asset.assetId)}/read`, { method: 'POST', body: { variantKey: 'original' } }); const link = document.createElement('a'); link.href = result.authorization.url; link.download = asset.filename; link.rel = 'noopener'; link.click() } catch (error) { message.value = errorText(error) } }
async function retryAsset(asset: any) { try { await $fetch(`/api/managed-sites/editor/assets/${encodeURIComponent(asset.assetId)}/processing-retry`, { method: 'POST', body: {} }); await loadWorkspace(); mediaOpen.value = true } catch (error) { message.value = errorText(error) } }
async function trashAsset(asset: any) { if (!confirm('將素材移到回收桶？使用中的素材仍不會被永久刪除。')) return; try { await $fetch(`/api/managed-sites/editor/assets/${encodeURIComponent(asset.assetId)}/trash`, { method: 'POST', body: {} }); await loadWorkspace(); mediaOpen.value = true } catch (error) { message.value = errorText(error) } }
async function createCollection() { if (!collectionName.value.trim()) return; try { await $fetch('/api/managed-sites/editor/collections', { method: 'POST', body: { name: collectionName.value, parentId: null, idempotencyKey: key('collection') } }); collectionName.value = ''; await loadWorkspace(); mediaOpen.value = true } catch (error) { message.value = errorText(error) } }
async function createTag() { if (!tagName.value.trim()) return; try { await $fetch('/api/managed-sites/editor/tags', { method: 'POST', body: { name: tagName.value, idempotencyKey: key('tag') } }); tagName.value = ''; await loadWorkspace(); mediaOpen.value = true } catch (error) { message.value = errorText(error) } }
async function organizeAsset(asset: any, collectionId: string) { try { await $fetch(`/api/managed-sites/editor/assets/${encodeURIComponent(asset.assetId)}/organize`, { method: 'POST', body: { collectionId: collectionId ? Number(collectionId) : null, tagIds: (asset.tags || []).map((tag: any) => tag.id), idempotencyKey: key('organize') } }); await loadWorkspace(); mediaOpen.value = true } catch (error) { message.value = errorText(error) } }
async function cropAndUse(asset: any) { try { const result: any = await $fetch(`/api/managed-sites/editor/assets/${encodeURIComponent(asset.assetId)}/transform`, { method: 'POST', body: { aspect: cropAspect.value, focalPoint: { x: focalX.value, y: focalY.value }, rotation: 0, expectedAssetVersion: asset.version, idempotencyKey: key('transform') } }); workspace.value.assets = workspace.value.assets.map((item: any) => item.assetId === asset.assetId ? result.asset : item); await replaceMedia(result.asset) } catch (error) { message.value = errorText(error) } }
async function proposeAi() { aiLoading.value = true; aiProposal.value = null; try { aiProposal.value = await $fetch('/api/managed-sites/editor/ai/propose', { method: 'POST', body: { pageId: page.value.pageId, expectedPageVersion: page.value.version, request: aiRequest.value, selectedMediaAssetIds: workspace.value.assets.filter((asset: any) => asset.status === 'ready').slice(0, 12).map((asset: any) => asset.assetId) } }) } catch (error) { message.value = errorText(error) } finally { aiLoading.value = false } }
async function applyAi() { try { const result: any = await $fetch('/api/managed-sites/editor/ai/apply', { method: 'POST', body: { proposalId: aiProposal.value.proposalId } }); page.value = result.results.at(-1)?.page || page.value; aiProposal.value = null; status.value = 'saved'; message.value = 'AI 提案已由你確認並套用到草稿；尚未發布。' } catch (error) { status.value = 'conflict'; message.value = errorText(error) } }

function blockTitle(block: any) { return block.data?.title || block.data?.eyebrow || block.type.replaceAll('_', ' ') }
onMounted(loadWorkspace)
</script>

<template>
  <main class="editor-shell">
    <header class="topbar">
      <div class="brand"><NuxtLink to="/customer/managed-sites">DiscoveryStack</NuxtLink><span>網站編輯器</span></div>
      <label class="page-select"><span class="sr-only">選擇頁面</span><select v-model="selectedPageId" @change="choosePage"><option v-for="item in workspace?.pages || []" :key="item.pageId" :value="item.pageId">{{ item.route }} · v{{ item.version }}</option></select></label>
      <div class="device-switch" aria-label="預覽裝置"><button v-for="item in ['desktop', 'tablet', 'mobile']" :key="item" :aria-pressed="device === item" @click="device = item as any">{{ item }}</button></div>
      <div class="save-state" :data-state="status" role="status">{{ { loading: '載入中', saved: '草稿已儲存', saving: '儲存中', publishing: '建立發布意圖', published: '已送交發布', error: '發生錯誤', conflict: '版本衝突' }[status] }}</div>
      <button class="quiet" :disabled="!undoVersions.length" @click="undo">復原</button><button class="quiet" :disabled="!redoVersions.length" @click="redo">重做</button><button class="quiet" @click="requestPreview">Server 預覽</button><button class="primary" :disabled="!workspace?.capabilities.canPublish || status === 'publishing'" @click="publish">發布</button>
    </header>

    <p v-if="message" class="notice" :class="{ danger: status === 'error' || status === 'conflict' }" role="alert">{{ message }}<button @click="message = ''">關閉</button></p>
    <section v-if="workspace && page" class="workbench">
      <aside class="structure-panel" aria-label="頁面結構">
        <div class="panel-heading"><div><span>PAGE STRUCTURE</span><h2>區塊</h2></div><button class="icon" title="重新載入" @click="loadPage(page.pageId)">↻</button></div>
        <ol class="block-list">
          <li v-for="(block, index) in page.sections" :key="block.blockId" draggable="true" :class="{ active: block.blockId === selectedBlockId, hidden: !block.visible }" @dragstart="draggedBlockId = block.blockId" @dragover.prevent @drop="dropBlock(Number(index))">
            <button class="block-name" @click="selectedBlockId = block.blockId"><span class="grip" aria-hidden="true">⠿</span><span><strong>{{ blockTitle(block) }}</strong><small>{{ block.type }} · {{ block.layoutVariant }}</small></span></button>
            <span class="reorder"><button :disabled="index === 0" :aria-label="`${blockTitle(block)} 上移`" @click="moveBlock(block.blockId, -1)">↑</button><button :disabled="index === page.sections.length - 1" :aria-label="`${blockTitle(block)} 下移`" @click="moveBlock(block.blockId, 1)">↓</button></span>
          </li>
        </ol>
        <details class="add-menu"><summary>＋ 新增區塊</summary><div><button v-for="item in blockCatalog" :key="item[0]" @click="addBlock(item[0]!)"><span>{{ item[1] }}</span><small>{{ item[0] }}</small></button></div></details>
        <button class="media-button" @click="mediaOpen = true">媒體庫 <span>{{ workspace.assets.length }}</span></button>
        <div class="quota"><div><span>儲存空間</span><strong>{{ quotaPercent }}%</strong></div><progress :value="quotaPercent" max="100"/><small>{{ (workspace.quota.originalBytesUsed / 1048576).toFixed(1) }} / {{ (workspace.quota.maxOriginalBytes / 1048576).toFixed(0) }} MB</small></div>
      </aside>

      <section class="canvas-wrap" aria-label="網站預覽">
        <div class="canvas" :data-device="device">
          <div class="browser-chrome"><i/><i/><i/><span>{{ workspace.project.website }}</span></div>
          <div class="page-preview" :data-theme="page.designTokens.palette">
            <article v-for="block in page.sections.filter((item: any) => item.visible)" :key="block.blockId" class="preview-block" :class="[`type-${block.type}`, { selected: block.blockId === selectedBlockId }]" tabindex="0" @click="selectedBlockId = block.blockId" @focus="selectedBlockId = block.blockId">
              <span class="block-chip">{{ block.type }}</span>
              <template v-if="block.type === 'hero'"><p class="eyebrow">{{ block.data.eyebrow || 'WELCOME' }}</p><h1 contenteditable="true" spellcheck="false" @blur="saveText('data.title', ($event.target as HTMLElement).innerText)">{{ block.data.title }}</h1><p>{{ block.data.description }}</p><div class="image-placeholder hero-image">主圖 · {{ block.mediaBindingIds[0] || '尚未選擇' }}</div></template>
              <template v-else-if="block.type === 'faq'"><h2>{{ block.data.title }}</h2><details v-for="item in block.data.items" :key="item.id"><summary>{{ item.question }}</summary><p>{{ item.answer }}</p></details></template>
              <template v-else-if="['services', 'case_studies', 'testimonials', 'team'].includes(block.type)"><h2>{{ block.data.title || block.type }}</h2><div class="card-grid"><div v-for="item in block.data.items || block.data.members" :key="item.id"><div class="image-placeholder"/><strong>{{ item.title || item.name || item.person }}</strong><p>{{ item.description || item.summary || item.quote || item.role }}</p></div></div></template>
              <template v-else-if="block.type === 'gallery_grid' || block.type === 'carousel'"><h2>{{ block.data.title || (block.type === 'carousel' ? '輪播' : '相簿') }}</h2><div class="gallery"><div v-for="binding in block.mediaBindingIds" :key="binding" class="image-placeholder">{{ binding }}</div></div><button v-if="block.type === 'carousel'" class="pause">暫停</button></template>
              <template v-else><h2>{{ block.data.title || block.type }}</h2><p>{{ block.data.description || block.data.nodes?.[0]?.text || '' }}</p><button v-if="block.data.primaryLink">{{ block.data.primaryLink.label }}</button></template>
            </article>
          </div>
        </div>
      </section>

      <aside class="property-panel" aria-label="區塊屬性">
        <div v-if="selectedBlock" class="properties">
          <div class="panel-heading"><div><span>PROPERTIES</span><h2>{{ selectedBlock.type }}</h2></div><button class="icon" title="複製區塊" @click="duplicateBlock">⧉</button></div>
          <label v-if="typeof selectedBlock.data.title === 'string'">標題<input :value="selectedBlock.data.title" maxlength="180" @change="saveText('data.title', ($event.target as HTMLInputElement).value)"></label>
          <label v-if="typeof selectedBlock.data.description === 'string'">說明<textarea :value="selectedBlock.data.description" maxlength="1600" rows="4" @change="saveText('data.description', ($event.target as HTMLTextAreaElement).value)"/></label>
          <label>版型<select :value="selectedBlock.layoutVariant" @change="updateVariant(($event.target as HTMLSelectElement).value)"><option v-for="variant in variants[selectedBlock.type]" :key="variant">{{ variant }}</option></select></label>
          <fieldset><legend>圖片焦點</legend><label>X<input v-model.number="focalX" type="range" min="0" max="1" step=".01"></label><label>Y<input v-model.number="focalY" type="range" min="0" max="1" step=".01"></label><label>裁切建議<select v-model="cropAspect"><option>free</option><option>1:1</option><option>4:3</option><option>3:2</option><option>16:9</option><option>portrait</option></select></label><button class="quiet full" @click="mediaOpen = true">選擇／替換這個位置</button></fieldset>
          <label>下架時間<input type="datetime-local" @change="scheduleBlock(($event.target as HTMLInputElement).value)"></label>
          <div class="checks"><button class="quiet" @click="toggleVisibility">{{ selectedBlock.visible ? '隱藏區塊' : '顯示區塊' }}</button><button class="danger-button" @click="removeBlock">刪除區塊</button></div>
          <div class="warnings"><h3>品質檢查</h3><p v-if="selectedBlock.mediaBindingIds.length && !page.mediaBindings.find((item: any) => selectedBlock.mediaBindingIds.includes(item.bindingId) && item.alt)">⚠ 圖片需要替代文字</p><p v-else>✓ 結構、行動版與基本無障礙規則有效</p><p v-if="selectedBlock.schedule">排程採 {{ selectedBlock.schedule.timezone }} 並由 server scheduler 驗證。</p></div>
        </div>
        <section class="ai-panel"><span>SCOPED AI EDITOR</span><h2>用自然語言改網站</h2><textarea v-model="aiRequest" maxlength="1200" rows="4" placeholder="例如：把這12張整理成案例區，首頁放6張"/><button class="primary full" :disabled="aiLoading || !aiRequest.trim()" @click="proposeAi">{{ aiLoading ? '建立安全提案…' : '預覽 AI 提案' }}</button><div v-if="aiProposal" class="proposal"><strong>{{ aiProposal.summary }}</strong><p>影響 {{ aiProposal.affectedBlockIds.length }} 個區塊 · {{ aiProposal.operations.length }} 項操作</p><ul><li v-for="warning in aiProposal.warnings" :key="warning">{{ warning }}</li></ul><details><summary>查看 structured diff</summary><pre>{{ JSON.stringify(aiProposal.diff, null, 2) }}</pre></details><button v-if="aiProposal.status === 'proposed'" class="primary full" @click="applyAi">確認並套用到草稿</button><p v-else>需要先補充選擇；沒有更動草稿，也沒有發布。</p></div></section>
        <section class="history"><span>VERSION HISTORY</span><button v-for="item in versions.slice(0, 12)" :key="item.fingerprint" :disabled="item.version === page.version" @click="restoreDraft(item.version)"><strong>v{{ item.version }}</strong><small>{{ item.publicationState }} · {{ new Date(item.createdAt).toLocaleString('zh-TW') }}</small></button></section>
      </aside>
    </section>

    <div v-if="mediaOpen" class="drawer-backdrop" @click.self="mediaOpen = false"><aside class="media-drawer" aria-label="媒體庫"><header><div><span>MEDIA VAULT</span><h2>你的媒體</h2></div><button class="icon" aria-label="關閉" @click="mediaOpen = false">×</button></header><div class="media-tools"><input v-model="mediaQuery" type="search" placeholder="搜尋檔名或標籤"><label class="upload">批次上傳<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple @change="uploadFiles(($event.target as HTMLInputElement).files)"></label></div><div class="organize-tools"><label>新增資料夾<span><input v-model="collectionName" maxlength="120"><button @click="createCollection">新增</button></span></label><label>新增標籤<span><input v-model="tagName" maxlength="80"><button @click="createTag">新增</button></span></label></div><div v-if="Object.keys(uploading).length" class="uploads"><div v-for="(progress, name) in uploading" :key="name"><span>{{ name }}</span><progress :value="Math.max(0, progress)" max="100"/><small>{{ progress < 0 ? '失敗／隔離' : `${progress}%` }}</small></div></div><div class="asset-grid"><article v-for="asset in filteredAssets" :key="asset.assetId"><button class="asset-choose" :disabled="asset.status !== 'ready'" @click="replaceMedia(asset)"><div class="asset-preview">{{ asset.width || '—' }}×{{ asset.height || '—' }}</div><strong>{{ asset.filename }}</strong><span :data-status="asset.status">{{ asset.status }}</span><small>{{ (asset.byteSize / 1048576).toFixed(2) }} MB · v{{ asset.version }}</small><small>{{ (asset.tags || []).map((tag: any) => `#${tag.name}`).join(' ') }}</small></button><label>資料夾<select :value="asset.collectionId || ''" @change="organizeAsset(asset, ($event.target as HTMLSelectElement).value)"><option value="">未分類</option><option v-for="collection in workspace.collections || []" :key="collection.id" :value="collection.id">{{ collection.name }}</option></select></label><div class="asset-actions"><button v-if="asset.status === 'ready' && (!asset.rightsMetadata?.publishAllowed || asset.visibility !== 'public')" @click="approveForPublicUse(asset)">核准公開</button><button v-if="asset.status === 'quarantined' || asset.status === 'failed'" @click="retryAsset(asset)">重試處理</button><button v-if="asset.status === 'ready'" @click="downloadOriginal(asset)">下載原圖</button><button v-if="asset.status === 'ready'" @click="trashAsset(asset)">回收</button></div></article></div><p class="drawer-note">原圖保持 immutable；替換只影響目前位置。private/internal、未確認使用權或已到期素材不會進入公開 artifact；scanner 未設定或失敗會留在隔離區。裁切與焦點採 server 驗證的 transformation 規格，並保留版本 lineage。</p></aside></div>
  </main>
</template>

